// Type check of the Vue components while vue-tsc cannot load TypeScript 7 (R-079): each .vue file is compiled by Vue's own compiler
// (script setup with the template inlined, as TypeScript) into .vue-check/, mirroring src/, and tsc checks the result with the project's
// settings. rootDirs lets the generated files import the real modules beside them; a component imported as './X.vue' resolves to the
// generated X.vue.ts, so props and emits are checked across components too. Errors are reported against the .vue file.
const fs = require('node:fs'), path = require('node:path'), { spawnSync } = require('node:child_process')
const { parse, compileScript } = require('vue/compiler-sfc')

const root = path.join(__dirname, '..'), out = path.join(root, '.vue-check')
const files = dir => fs.readdirSync(dir, { withFileTypes: true }).flatMap(entry => entry.isDirectory() ? files(path.join(dir, entry.name)) : entry.name.endsWith('.vue') ? [path.join(dir, entry.name)] : [])
// The text between the angle brackets of `defineProps<…>`, with nested brackets and strings skipped.
function typeArgument(source, marker) {
  const start = source.indexOf(marker)
  if (start < 0) return null
  let depth = 0, quote = null
  for (let index = start + marker.length - 1; index < source.length; index++) {
    const char = source[index]
    if (quote) { if (char === quote && source[index - 1] !== '\\') quote = null; continue }
    if (char === '"' || char === "'" || char === '`') quote = char
    else if ('<{(['.includes(char)) depth++
    else if ('>})]'.includes(char) && !(char === '>' && source[index - 1] === '=')) { depth--; if (depth === 0) return source.slice(start + marker.length, index) }
  }
  return null
}
fs.rmSync(out, { recursive: true, force: true })
const sources = files(path.join(root, 'src', 'vue'))
for (const file of sources) {
  const relative = path.relative(root, file)
  const { descriptor, errors } = parse(fs.readFileSync(file, 'utf8'), { filename: file })
  if (errors.length) { console.error(relative + ': ' + errors.map(error => error.message).join('; ')); process.exit(1) }
  // The compiler types the props of script setup as any; the type written in defineProps<…>() is put back so props are checked in the
  // script and the template.
  let code = compileScript(descriptor, { id: relative, inlineTemplate: true }).content
  const props = typeArgument(descriptor.scriptSetup?.content || '', 'defineProps<')
  if (props) code = code.replace('setup(__props: any', `setup(__props: ${props}`)
  const target = path.join(out, relative + '.ts')
  fs.mkdirSync(path.dirname(target), { recursive: true })
  fs.writeFileSync(target, `// Generated by scripts/check-vue.cjs from ${relative.split(path.sep).join('/')}\n${code}`)
}
const base = JSON.parse(fs.readFileSync(path.join(root, 'tsconfig.json'), 'utf8'))
fs.writeFileSync(path.join(out, 'tsconfig.json'), JSON.stringify({ compilerOptions: { ...base.compilerOptions, rootDirs: ['../src', './src'], noUnusedLocals: false, noUnusedParameters: false },
  include: ['./src/**/*.vue.ts', '../src/vite-env.d.ts', '../src/vue/shims.d.ts'] }, null, 1))
const tsc = path.join(root, 'node_modules', '.bin', process.platform === 'win32' ? 'tsc.cmd' : 'tsc')
const result = spawnSync(`"${tsc}" -p tsconfig.json`, { cwd: out, encoding: 'utf8', shell: true })
// Two kinds of diagnostics come from compiling the template, not from the code: an arrow function's parameters in an event binding are not
// typed from the component's emits (TS7006), and a v-if does not narrow inside the handlers and blocks below it (TS18047, TS18048, TS2531, TS2532). vue-tsc types
// both; here they are counted and left out, only inside the compiled template (after its render function starts), never in the script.
const NOISE = new Set(['TS7006', 'TS18047', 'TS18048', 'TS2531', 'TS2532'])
const renderStart = new Map()
const errors = [], skipped = {}
for (const block of `${result.stdout || ''}${result.stderr || ''}`.split(/\r?\n(?=\S)/).filter(Boolean)) {
  const match = /^(.+?)\((\d+),\d+\): error (TS\d+)/.exec(block)
  if (match && match[1].endsWith('.vue.ts') && NOISE.has(match[3])) {
    const file = path.resolve(out, match[1])
    if (!renderStart.has(file)) renderStart.set(file, fs.readFileSync(file, 'utf8').split(/\r?\n/).findIndex(line => /return \(_ctx(: any)?, ?_cache(: any)?\) =>/.test(line)) + 1)
    const start = renderStart.get(file)
    if (start > 0 && Number(match[2]) >= start) { skipped[match[3]] = (skipped[match[3]] || 0) + 1; continue }
  }
  errors.push(block)
}
const noise = Object.entries(skipped).map(([code, count]) => `${code} ×${count}`).join(', ')
if (errors.length) { console.error(errors.join('\n').split('.vue.ts').join('.vue')); console.error(`${errors.length} error(s), at lines of the compiled component (run node scripts/check-vue.cjs --keep to read .vue-check/)${noise ? `; template-only diagnostics left out: ${noise}` : ''}`); process.exit(1) }
if (result.status !== 0 && !noise) { console.error(`${result.stdout || ''}${result.stderr || ''}`); process.exit(1) }
if (!process.argv.includes('--keep')) fs.rmSync(out, { recursive: true, force: true })
console.log(`Vue type check: ${sources.length} components, no errors${noise ? ` (template-only diagnostics left out: ${noise})` : ''}.`)
